"""Tests for subject.parse_event_bus."""

import pytest

from subject import EventBusContractShapeError, parse_event_bus


def test_missing_event_bus_yields_no_subscriptions():
    result = parse_event_bus({})
    assert list(result.subscriptions) == []


def test_none_event_bus_yields_no_subscriptions():
    result = parse_event_bus({"event_bus": None})
    assert list(result.subscriptions) == []


def test_empty_event_bus_dict_yields_no_subscriptions():
    result = parse_event_bus({"event_bus": {}})
    assert list(result.subscriptions) == []


def test_event_bus_not_a_mapping_raises():
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": ["topic.a"]})


def test_event_bus_string_raises():
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": "subscribe_topics"})


def test_unknown_event_bus_key_raises():
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": {"publish_topics": ["a"]}})


def test_only_unknown_keys_raises():
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": {"publish": []}})


def test_classic_topics_parsed_in_order():
    result = parse_event_bus(
        {"event_bus": {"subscribe_topics": ["sensor.temp", "sensor.humidity", "alert.high"]}}
    )
    assert [s.topic for s in result.subscriptions] == [
        "sensor.temp",
        "sensor.humidity",
        "alert.high",
    ]


def test_classic_empty_list_ok():
    result = parse_event_bus({"event_bus": {"subscribe_topics": []}})
    assert list(result.subscriptions) == []


def test_classic_not_a_list_raises():
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": {"subscribe_topics": "sensor.temp"}})


def test_classic_non_string_entry_raises():
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": {"subscribe_topics": ["a", 7]}})


def test_nested_single_topic():
    result = parse_event_bus({"event_bus": {"subscribe": [{"topic": "orders.created"}]}})
    assert [s.topic for s in result.subscriptions] == ["orders.created"]


def test_nested_multiple_topics_in_order():
    result = parse_event_bus(
        {"event_bus": {"subscribe": [{"topic": "a"}, {"topic": "b"}, {"topic": "c"}]}}
    )
    assert [s.topic for s in result.subscriptions] == ["a", "b", "c"]


def test_nested_empty_list_ok():
    result = parse_event_bus({"event_bus": {"subscribe": []}})
    assert list(result.subscriptions) == []


def test_nested_not_a_list_raises():
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": {"subscribe": {"topic": "a"}}})


def test_nested_entry_not_a_mapping_raises():
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": {"subscribe": ["a"]}})


def test_nested_entry_missing_topic_raises():
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": {"subscribe": [{}]}})


def test_nested_entry_non_string_topic_raises():
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": {"subscribe": [{"topic": 123}]}})


def test_nested_entry_none_topic_raises():
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus({"event_bus": {"subscribe": [{"topic": None}]}})


def test_nested_consumer_group_rejected():
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus(
            {"event_bus": {"subscribe": [{"topic": "a", "consumer_group": "cg-1"}]}}
        )


def test_nested_unknown_entry_key_rejected():
    with pytest.raises(EventBusContractShapeError):
        parse_event_bus(
            {"event_bus": {"subscribe": [{"topic": "a", "durability": "high"}]}}
        )


def test_both_shapes_classic_first():
    result = parse_event_bus(
        {
            "event_bus": {
                "subscribe_topics": ["classic.one", "classic.two"],
                "subscribe": [{"topic": "nested.one"}, {"topic": "nested.two"}],
            }
        }
    )
    assert [s.topic for s in result.subscriptions] == [
        "classic.one",
        "classic.two",
        "nested.one",
        "nested.two",
    ]
